// Original hypothetical teaching examples. No market feed or randomness.
export const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const compound=(year,rate=.1,initial=100)=>({year,simple:initial*(1+rate*year),compound:initial*(1+rate)**year});
export const allocation=(weightA)=>({weightA,weightB:100-weightA,contributionA:weightA/100*10,contributionB:(100-weightA)/100*-5,returnPct:weightA/100*10+(100-weightA)/100*-5});
export const callProfit=(price,strike=100,premium=5)=>Math.max(price-strike,0)-premium;
export const drawdownPath=[100,80,100].map((wealth,index)=>({index,wealth,peak:100,loss:100*(1-wealth/100)}));
export const VISUALS={
1:{title:'A portfolio return is a weighted sum',step:'lab',prompt:'Predict: does a 40% share allocation mean that shares contribute 40 percentage points of return?',kind:'allocation',frames:[{label:'Choose starting weights',detail:'Cash 20%, bonds 40%, shares 40% of starting wealth £1,000. Weights sum to 100%.'},{label:'Apply one return to each sleeve',detail:'Hypothetical one-year returns: cash 2%, bonds 3%, shares 8%. No fees, flows or rebalancing.'},{label:'Add the contributions',detail:'0.20×2 +0.40×3 +0.40×8 =4.8%. The return contributions are 0.4, 1.2 and 3.2 percentage points.'},{label:'Translate return into wealth',detail:'£1,000×1.048 =£1,048. Shares contribute 3.2 percentage points, not 40. A different scenario can produce a loss.'}],limit:'One invented year, fixed starting weights and zero costs. This is arithmetic, not a suitable allocation recommendation.'},
2:{title:'Compounding earns growth on earlier growth',step:'compound',prompt:'Predict: at 10% per year, will year 5 wealth be £150 or more than £150?',kind:'compound',frames:Array.from({length:6},(_,year)=>{const v=compound(year);return {label:`Year ${year}`,detail:`Starting £100, constant 10% annual effective rate: compound £${v.compound.toFixed(2)}; simple growth £${v.simple.toFixed(2)}. ${year?'Compound growth applies to the previous balance.':'Both begin at the same £100.'}`};}),limit:'Assumed constant annual effective rate; no contributions, fees, taxes or inflation. Real investment returns are not fixed.'},
3:{title:'A split changes share units, not wealth by itself',step:'adjustment',prompt:'Predict: if a two-for-one split halves the price, has the holding lost half its value?',kind:'split',frames:[{label:'Before the split',detail:'One share at £100: holding value £100.'},{label:'Change the units',detail:'A two-for-one split replaces one share with two. The mechanical price per share becomes £50.'},{label:'Check the holding',detail:'Two shares×£50 =£100. The split alone did not halve wealth. Raw100→50 looks like−50% if the unit change is ignored.'},{label:'Compare a consistent basis',detail:'Restate the old price on the new-share basis:50→50 gives0% price return for this split-only example. Distributions and market moves require separate treatment.'}],limit:'Pure hypothetical two-for-one split. Adjustments must follow documented source conventions; do not infer a split from a price drop alone.'},
4:{title:'The mean can hide a wide spread',step:'spread',prompt:'Predict: can a sample with a mean of1% still contain both negative and positive months?',kind:'sample',frames:[{label:'Keep every observation',detail:'Six invented monthly returns:−3,−1,0,1,2,7 percent. Each bar is one observation, not a future probability.'},{label:'Locate the mean',detail:'The sum is6%; divide by six observations to get mean 1%.'},{label:'Keep the deviations',detail:'Deviations from 1% are−4,−2,−1,0,1,6 percentage points. The squared deviations sum to 58.'},{label:'Use the sample denominator',detail:'Sample SD=√(58/(6−1))≈3.406 percentage points. Dividing by n−1 is the sample convention. Neither mean nor SD is a future guarantee.'}],limit:'Six synthetic observations; descriptive statistics only. Annual scaling and probability forecasts need additional assumptions.'},
5:{title:'Recovery does not erase the earlier drawdown',step:'drawdown',prompt:'Predict: after−20% followed by+25%, is maximum drawdown zero because wealth recovers?',kind:'drawdown',frames:drawdownPath.map((v,i)=>({label:['Start with the initial peak','Fall below the peak','Recover to the peak'][i],detail:[`Wealth 100; running peak 100. Current loss from peak0%. Include starting wealth in the comparison.`,`Wealth 80 after−20%. Loss from peak=(1−80/100)×100=20%.`,`Wealth 100 after+25% on 80. Current drawdown returns to 0%, but the largest previously observed loss remains 20%.`][i]})),limit:'Two invented periods, no costs or flows. Drawdown is measured at observed endpoints and can miss intraperiod lows; it is not a future loss bound.'},
6:{title:'Weights control the same-period portfolio return',step:'weights',prompt:'Predict: with A returning +10% and B returning −5%, which weight produces zero portfolio return?',kind:'weights',frames:[0,25,100/3,50,75,100].map(weight=>{let a=allocation(weight);return {label:`A weight ${weight.toFixed(2)}%`,weight,detail:`A ${weight.toFixed(2)}%, B ${a.weightB.toFixed(2)}%. Weighted contributions ${a.contributionA.toFixed(2)} and ${a.contributionB.toFixed(2)} percentage points; portfolio return ${a.returnPct.toFixed(2)}%.`};}),limit:'One hypothetical paired period, long-only weights summing to 100%, no costs or flows. This demonstrates weighting, not proof of risk reduction; diversification also depends on joint return behaviour.'},
7:{title:'A call payoff and its profit are different',step:'call',prompt:'Predict: does finishing above the strike guarantee a profit after paying the premium?',kind:'call',frames:[80,100,105,120].map(price=>({label:`Terminal price £${price}`,price,detail:`Strike £100; premium £5. Payoff=max(${price}−100,0)=£${Math.max(price-100,0)}. Profit=payoff−5=£${callProfit(price)}. ${price===105?'Break-even occurs at £105, not £100.':'The premium is paid even when the option expires without value.'}`})),limit:'One hypothetical European call at expiry, one unit, no fees, interest, dividends or exercise complications. The premium here is assumed, not a model-derived fair value.'},
8:{title:'Information must arrive before a trade can use it',step:'timing',prompt:'Predict: can a rule based on tonight’s close earn the return that happened before tonight’s close?',kind:'flow',frames:[{label:'Observe the close',detail:'At day t close, the three required closes are now known. Earlier prices cannot be traded retroactively.'},{label:'Form the signal',detail:'Compare close[t] with the trailing three-close mean. The signal uses no later close.'},{label:'Execute at the next open',detail:'The earliest eligible trade in this lesson is open[t+1]. Pay the declared transaction cost at execution.'},{label:'Earn the holding-period return',detail:'The chosen position earns open[t+1]→open[t+2], then later signals control later intervals. Cash earns the declared cash rate.'}],limit:'Illustrative lesson execution convention. Real delays, available liquidity and slippage may require a later or different execution model.'},
9:{title:'Freeze the question before inspecting evaluation results',step:'plan',prompt:'Predict: does renaming an already-inspected dataset “evaluation” make it an unseen test?',kind:'flow',frames:[{label:'Develop on earlier evidence',detail:'Use development evidence to choose a bounded rule and assumptions. Record every tried alternative, including losing ones.'},{label:'Freeze the analysis plan',detail:'Record question, inputs, benchmark, costs and stopping rule before revealing the evaluation outcomes.'},{label:'Inspect evaluation once as planned',detail:'Run the declared analysis and retain both predefined cost cases. The course’s source is public: a local gate cannot prove genuinely unseen data or external preregistration.'},{label:'Report deviations and exposure',detail:'If you inspect, tune and rerun, disclose the sequence and label affected conclusions exploratory. A new label does not restore independence.'}],limit:'A teaching sequence, not proof of independent validation. This diagram reveals no capstone evaluation numbers.'},
10:{title:'A conclusion should trace back to evidence',step:'review',prompt:'Predict: which attachment would let someone check the numbers in your memo?',kind:'flow',frames:[{label:'Identify the input',detail:'Name the synthetic dataset version, dates and conventions. Preserve the input file and any prior exposure.'},{label:'Preserve the plan and ledger',detail:'Keep fixed plan versions, every trial and complete calculation rows, including costs and the matching benchmark.'},{label:'Write a conditional claim',detail:'Connect the memo’s headline to a row, hand check and limitation. A losing result or insufficient evidence can be a sound conclusion.'},{label:'Review and revise',detail:'Use each rubric criterion to find a specific weakness, revise the claim and preserve the earlier draft. A self-score is not independent validation.'}],limit:'Evidence tracing supports self-review. It does not certify general competence, investability or an accredited credential.'}
};
